const state={user:null,settings:{},properties:[],favorites:new Set(),compare:new Set(),view:"home",filters:{purpose:"venda"},chat:{open:false,contacts:[],with:null,poll:null}};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const money=v=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0}).format(Number(v)||0);
const statusLabel={draft:"Rascunho",pending:"Aguardando análise",published:"Publicado",paused:"Pausado",sold:"Vendido",rented:"Alugado",archived:"Arquivado",new:"Novo",contacted:"Contatado",qualified:"Qualificado",visit:"Visita",proposal:"Proposta",negotiation:"Negociação",closed:"Fechado",lost:"Perdido"};
async function api(url,opt={}){const headers={...(opt.body instanceof FormData?{}:{"Content-Type":"application/json"}),...(opt.headers||{})};const r=await fetch(url,{...opt,headers});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Não foi possível concluir a operação.");return d}
function toast(msg,type="ok"){const t=$("#toast");t.textContent=msg;t.className="show "+type;clearTimeout(toast.t);toast.t=setTimeout(()=>t.className="",3200)}
async function init(){state.settings=await api("/api/settings");state.user=await api("/api/auth/me");document.documentElement.style.setProperty("--accent",state.settings.primary_color||"#b08d57");await loadFavorites();renderHome();if(state.user)refreshChatBadge()}
async function loadFavorites(){if(!state.user||state.user.role!=="customer"){state.favorites=new Set();return}try{state.favorites=new Set((await api("/api/me/favorites")).map(p=>p.id))}catch{}}
function shell(body,active="home"){const s=state.settings;return `<header class="site-header"><div class="container nav"><a class="brand" href="#" onclick="return home(event)"><span class="brand-mark">I</span><span>${esc(s.company_name||"Imob Pro")}</span></a><nav><a class="${active==="buy"?"active":""}" href="#" onclick="return searchPage(event,'venda')">Comprar</a><a class="${active==="rent"?"active":""}" href="#" onclick="return searchPage(event,'aluguel')">Alugar</a><a href="#" onclick="return searchPage(event,'')">Imóveis</a><a href="#" onclick="return ownerInfo(event)">Anunciar</a></nav><div class="nav-actions"><button class="icon-btn" title="Favoritos" onclick="account('favorites')">♡</button><button class="icon-btn compare-nav" title="Comparar" onclick="openCompare()">⇄<span>${state.compare.size||''}</span></button><button class="btn btn-dark" onclick="openAuth()">${state.user?esc(state.user.name.split(' ')[0]):"Entrar"}</button><button class="mobile-menu" onclick="openMenu()">☰</button></div></div></header>${body}<footer class="footer"><div class="container footer-grid"><div><div class="brand footer-brand"><span class="brand-mark">I</span>${esc(s.company_name||"Imob Pro")}</div><p>${esc(s.hero_subtitle||"Uma experiência imobiliária completa para comprar, alugar e anunciar.")}</p><div class="socials"><a href="${esc(s.instagram||"#")}" target="_blank" rel="noopener">Instagram</a><a href="${esc(s.facebook||"#")}" target="_blank" rel="noopener">Facebook</a><a href="${esc(s.linkedin||"#")}" target="_blank" rel="noopener">LinkedIn</a></div></div><div><h4>Comprar</h4><a href="#" onclick="return searchPage(event,'venda')">Imóveis à venda</a><a href="#" onclick="return searchPage(event,'venda','Apartamento')">Apartamentos</a><a href="#" onclick="return searchPage(event,'venda','Casa')">Casas</a><a href="#" onclick="return searchPage(event,'venda','Comercial')">Comerciais</a></div><div><h4>Alugar</h4><a href="#" onclick="return searchPage(event,'aluguel')">Imóveis para alugar</a><a href="#" onclick="return ownerInfo(event)">Anunciar imóvel</a><a href="#" onclick="return account('saved')">Minhas buscas</a><a href="#" onclick="return account('collections')">Minhas coleções</a></div><div><h4>Atendimento</h4><a href="https://wa.me/${esc((s.whatsapp||"").replace(/\D/g,""))}" target="_blank" rel="noopener">WhatsApp</a><a href="mailto:${esc(s.email||"")}">${esc(s.email||"E-mail")}</a><span>${esc(s.phone||"")}</span><span>${esc(s.city||"")}</span><button class="footer-link-btn" onclick="openChat()">Falar com a equipe</button></div><div><h4>Imob Pro</h4><a href="#" onclick="return ownerInfo(event)">Para proprietários</a><a href="#" onclick="return footerNotice(event,'Sobre a plataforma')">Sobre</a><a href="#" onclick="return footerNotice(event,'Ajuda')">Ajuda</a><a href="#" onclick="return footerNotice(event,'Política de privacidade')">Privacidade</a></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} ${esc(s.company_name||"Imob Pro")}</span><div class="footer-legal"><a href="#" onclick="return footerNotice(event,'Privacidade')">Privacidade</a><a href="#" onclick="return footerNotice(event,'Termos de uso')">Termos</a><a href="#" onclick="return footerNotice(event,'Cookies')">Cookies</a><a href="#" onclick="return state.user?accountPrivacy():openAuth('login')">Preferências de dados</a></div></div></footer>${chatLauncher()}<div id="chatRoot"></div>`}
function footerNotice(e,title){if(e)e.preventDefault();openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">INFORMAÇÕES</div><h2>${esc(title)}.</h2><p>Esta seção fica pronta para receber o conteúdo jurídico e as políticas específicas da imobiliária durante a implantação.</p><button class="btn btn-gold full" onclick="closeModal()">Fechar</button>`);return false}
function home(e){if(e)e.preventDefault();state.view="home";renderHome();return false}
async function renderHome(){const props=await api("/api/properties?purpose=venda");state.properties=props;const s=state.settings;const neighborhoods=[...new Set(props.map(p=>p.neighborhood).filter(Boolean))].slice(0,6);const featured=props.slice(0,6);document.title=`${s.company_name||"Imob Pro"} — Imóveis`;$("#site").innerHTML=shell(`<main><section class="hero"><div class="hero-image"></div><div class="hero-overlay"></div><div class="container hero-content"><div class="eyebrow light">PLATAFORMA IMOBILIÁRIA</div><h1>${esc(s.hero_title||"Encontre o lugar onde sua próxima história começa.")}</h1><p>${esc(s.hero_subtitle||"Uma experiência completa para descobrir, comparar e negociar imóveis.")}</p><div class="search-panel"><div class="search-tabs"><button class="tab active" data-purpose="venda">Comprar</button><button class="tab" data-purpose="aluguel">Alugar</button></div><div class="search-row"><label>Localização<input id="homeQ" placeholder="Cidade, bairro ou endereço" autocomplete="off"></label><label>Tipo<select id="homeType"><option value="">Todos</option><option>Apartamento</option><option>Casa</option><option>Comercial</option><option>Terreno</option></select></label><label>Preço máximo<input id="homeMax" type="number" placeholder="R$"></label><button class="btn btn-gold search-btn" onclick="runHomeSearch()">Buscar imóveis <span>→</span></button></div><div class="quick"><button onclick="quickSearch('venda','Apartamento')">Apartamentos</button><button onclick="quickSearch('venda','Casa')">Casas</button><button onclick="quickSearch('aluguel','')">Aluguel</button><button onclick="searchPage(event,'')">Todos os filtros</button></div></div><div class="hero-trust"><span>Busca inteligente</span><span>Visitas online</span><span>Atendimento humano</span></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">SELEÇÃO</div><h2>Imóveis em destaque</h2></div><button class="text-btn" onclick="searchPage(event,'')">Ver todos →</button></div><div class="property-grid">${featured.map(propertyCard).join("")}</div></div></section><section class="section soft"><div class="container"><div class="section-head"><div><div class="eyebrow">EXPLORAR</div><h2>Encontre por região.</h2></div><button class="text-btn" onclick="searchPage(event,'')">Abrir busca →</button></div><div class="neighborhood-grid">${neighborhoods.map(n=>`<button class="neighborhood-card" onclick="searchByNeighborhood(${JSON.stringify(n)})"><span>REGIÃO</span><strong>${esc(n)}</strong><small>Ver imóveis disponíveis →</small></button>`).join("")}</div></div></section><section class="section"><div class="container feature-band"><div><div class="eyebrow">PARA PROPRIETÁRIOS</div><h2>Seu imóvel merece uma experiência à altura.</h2><p>Publique, acompanhe a aprovação e mantenha seus dados atualizados em um portal próprio.</p><button class="btn btn-dark" onclick="ownerInfo(event)">Quero anunciar</button></div><div class="feature-art"><span>IMOB</span><strong>PRO</strong><small>TECNOLOGIA · CRM · ATENDIMENTO</small></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">JORNADA</div><h2>Da descoberta ao atendimento.</h2></div></div><div class="steps"><div><b>01</b><h3>Encontre</h3><p>Pesquise por localização, preço, tipo e dezenas de características.</p></div><div><b>02</b><h3>Compare</h3><p>Salve favoritos, crie coleções e compare imóveis lado a lado.</p></div><div><b>03</b><h3>Converse</h3><p>Fale com a equipe, agende visitas e acompanhe sua jornada.</p></div></div></div></section><section class="section soft"><div class="container"><div class="section-head"><div><div class="eyebrow">CONFIANÇA</div><h2>Uma experiência pensada para decisões importantes.</h2></div></div><div class="trust-grid"><div><strong>Informação organizada</strong><p>Preço, características, custos e localização reunidos na mesma experiência.</p></div><div><strong>Atendimento humano</strong><p>Chat persistente para conversar com a equipe sem perder o histórico.</p></div><div><strong>Jornada conectada</strong><p>Favoritos, buscas, visitas e notificações acompanham o cliente.</p></div><div><strong>Gestão profissional</strong><p>CRM, leads, tarefas, imóveis e permissões para a equipe.</p></div></div></div></section><section class="section faq-section"><div class="container faq-wrap"><div><div class="eyebrow">DÚVIDAS</div><h2>Antes de escolher, pergunte.</h2><p class="muted-copy">A equipe pode ajudar com imóveis, visitas, disponibilidade e próximos passos.</p><button class="btn btn-gold" onclick="openChat()">Falar com a equipe</button></div><div class="faq-list"><details><summary>Posso salvar imóveis?</summary><p>Sim. Crie uma conta de cliente para salvar favoritos, buscas e coleções.</p></details><details><summary>Posso agendar uma visita?</summary><p>Sim. Na página do imóvel você pode solicitar uma visita e a equipe acompanha a solicitação.</p></details><details><summary>O proprietário pode editar o anúncio?</summary><p>Sim. O anunciante possui um portal próprio e só consegue editar os imóveis vinculados à própria conta.</p></details></div></div></section></main>` ,"home");$$('.search-tabs .tab').forEach(b=>b.onclick=()=>{$$('.search-tabs .tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.filters.purpose=b.dataset.purpose});}
function propertyCard(p){const fav=state.favorites.has(p.id),cmp=state.compare.has(p.id);return `<article class="property-card interactive-card" data-property-card="${p.id}"><div class="property-media"><img src="${esc(p.cover_image||"")}" alt="${esc(p.title)}" loading="lazy" decoding="async" width="900" height="620"><div class="badges"><span>${p.purpose==='aluguel'?'ALUGUEL':'VENDA'}</span>${p.status==='published'?'<span class="verified-badge">VERIFICADO</span>':''}</div><div class="card-actions"><button class="round fav-btn" data-id="${p.id}" title="Favoritar" aria-label="Favoritar ${esc(p.title)}" onclick="toggleFavorite(event,${p.id})">${fav?'♥':'♡'}</button><button class="round" title="Compartilhar" aria-label="Compartilhar" onclick="shareProperty(event,${p.id})">↗</button><button class="round" title="Visão rápida" aria-label="Visão rápida" onclick="openQuickView(event,${p.id})">＋</button></div></div><div class="property-body"><div class="property-price">${money(p.price)}${p.purpose==='aluguel'?'<small>/mês</small>':''}</div><h3>${esc(p.title)}</h3><p class="location">${esc(p.neighborhood)} · ${esc(p.city)}</p><div class="specs"><span>${p.bedrooms} quartos</span><span>${p.suites||0} suítes</span><span>${p.bathrooms} ban.</span><span>${p.parking} vagas</span><span>${p.area} m²</span></div><div class="card-actions-row"><button class="mini-btn" onclick="openQuickView(event,${p.id})">Visão rápida</button><button class="mini-btn ${cmp?'selected':''}" onclick="toggleCompare(event,${p.id})">${cmp?'✓ Comparando':'＋ Comparar'}</button><button class="card-link" onclick="openProperty(${p.id})">Ver imóvel <span>→</span></button></div></div></article>`}
let regionCarousel={name:"",items:[],index:0};
async function searchByNeighborhood(name){
  try{
    const items=await api('/api/properties?'+new URLSearchParams({neighborhood:name,purpose:"venda"}));
    regionCarousel={name,items,index:0};
    if(!items.length){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">REGIÃO</div><h2>${esc(name)}.</h2><p>Nenhum imóvel publicado foi encontrado nesta região no momento.</p><button class="btn btn-gold full" onclick="closeModal();searchPage(event,'')">Ver todos os imóveis</button>`);return;}
    renderRegionCarousel();
  }catch(e){toast(e.message,'error')}
}
function renderRegionCarousel(){
  const p=regionCarousel.items[regionCarousel.index];
  const total=regionCarousel.items.length;
  openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">REGIÃO · ${esc(regionCarousel.name)}</div><div class="region-carousel-head"><div><h2>Imóveis em ${esc(regionCarousel.name)}.</h2><p>${total} imóvel(is) disponível(is).</p></div><span>${regionCarousel.index+1} / ${total}</span></div><div class="region-carousel-card"><div class="region-carousel-image"><img src="${esc(p.cover_image||'')}" alt="${esc(p.title)}"></div><div class="region-carousel-info"><div class="property-price">${money(p.price)}${p.purpose==='aluguel'?'<small>/mês</small>':''}</div><h3>${esc(p.title)}</h3><p class="location">${esc(p.neighborhood)} · ${esc(p.city)}</p><div class="specs"><span>${p.bedrooms||0} quartos</span><span>${p.suites||0} suítes</span><span>${p.bathrooms||0} ban.</span><span>${p.parking||0} vagas</span><span>${p.area||0} m²</span></div><button class="btn btn-dark full" onclick="closeModal();openProperty(${p.id})">Ver imóvel →</button></div></div><div class="region-carousel-controls"><button class="btn btn-light" onclick="moveRegionCarousel(-1)" ${regionCarousel.index===0?'disabled':''}>← Anterior</button><div class="region-dots">${regionCarousel.items.map((_,i)=>`<button class="region-dot ${i===regionCarousel.index?'active':''}" aria-label="Imóvel ${i+1}" onclick="regionCarousel.index=${i};renderRegionCarousel()"></button>`).join('')}</div><button class="btn btn-light" onclick="moveRegionCarousel(1)" ${regionCarousel.index===total-1?'disabled':''}>Próximo →</button></div><button class="text-btn full region-all-btn" onclick="closeModal();searchPage(event,'');setTimeout(()=>{const q=document.querySelector('#fq');if(q){q.value=${JSON.stringify(regionCarousel.name)};applyFilters();}},0)">Ver todos desta região →</button>`);
}
function moveRegionCarousel(delta){const next=regionCarousel.index+delta;if(next<0||next>=regionCarousel.items.length)return;regionCarousel.index=next;renderRegionCarousel()}

async function searchPage(e,purpose="",type=""){if(e)e.preventDefault();state.filters={purpose,type};const qs=new URLSearchParams();if(purpose)qs.set('purpose',purpose);if(type)qs.set('type',type);const props=await api('/api/properties?'+qs);state.properties=props;$("#site").innerHTML=shell(`<main class="search-page"><div class="container"><div class="page-top"><div><div class="eyebrow">EXPLORAR</div><h1>Encontre seu próximo imóvel.</h1><p>${props.length} resultado(s) encontrados</p></div><button class="btn btn-light" onclick="saveCurrentSearch()">＋ Salvar busca</button></div><div class="filter-bar"><input id="fq" placeholder="Cidade, bairro ou palavra-chave"><select id="ftype"><option value="">Tipo</option><option>Apartamento</option><option>Casa</option><option>Comercial</option><option>Terreno</option></select><input id="fmin" type="number" placeholder="Preço mín."><input id="fmax" type="number" placeholder="Preço máx."><select id="fbed"><option value="">Quartos</option><option value="1">1+</option><option value="2">2+</option><option value="3">3+</option><option value="4">4+</option></select><button class="btn btn-dark" onclick="applyFilters()">Filtrar</button></div><div class="results-layout"><aside class="map-placeholder"><div class="map-grid"></div><div class="map-copy"><span>MAPA</span><strong>Explore por região</strong><p>O mapa pode receber a integração cartográfica da implantação.</p></div></aside><section><div class="results-head"><span>${props.length} imóveis</span><select onchange="sortProperties(this.value)"><option value="recent">Mais recentes</option><option value="priceAsc">Menor preço</option><option value="priceDesc">Maior preço</option></select></div><div id="results" class="property-grid">${props.map(propertyCard).join("")||empty("Nenhum imóvel encontrado","Tente mudar os filtros.")}</div></section></div></div></main>` ,purpose==='venda'?'buy':purpose==='aluguel'?'rent':'home');return false}
async function applyFilters(){const q=new URLSearchParams();const f={purpose:state.filters.purpose,type:$("#ftype").value,q:$("#fq").value,minPrice:$("#fmin").value,maxPrice:$("#fmax").value,bedrooms:$("#fbed").value};Object.entries(f).forEach(([k,v])=>v&&q.set(k,v));const ps=await api('/api/properties?'+q);state.properties=ps;$("#results").innerHTML=ps.map(propertyCard).join("")||empty("Nenhum imóvel encontrado","Tente mudar os filtros.");$(".page-top p").textContent=ps.length+" resultado(s) encontrados"}
function sortProperties(v){const a=[...state.properties];a.sort((x,y)=>v==='priceAsc'?x.price-y.price:v==='priceDesc'?y.price-x.price:new Date(y.updated_at)-new Date(x.updated_at));$("#results").innerHTML=a.map(propertyCard).join("")}
async function openProperty(id){const p=await api('/api/properties/'+id);try{await api('/api/properties/'+id+'/view',{method:'POST',body:JSON.stringify({source:'property-page'})})}catch{}const related=state.properties.filter(x=>x.id!==p.id).slice(0,3);const cover=p.cover_image||"";const mapQuery=encodeURIComponent([p.address,p.neighborhood,p.city].filter(Boolean).join(', '));const totalMonthly=(Number(p.condo)||0)+(Number(p.iptu)||0);$("#site").innerHTML=shell(`<main class="detail-page"><div class="container"><button class="back-btn" onclick="home()">← Voltar</button><div class="gallery premium-gallery"><div class="gallery-main"><img src="${esc(cover)}" alt="${esc(p.title)}" width="1400" height="900"></div><div class="gallery-side">${(p.images.length?p.images:[{filename:cover}]).slice(0,3).map(x=>`<img src="${esc(/^https?:/.test(x.filename||'')?x.filename:'/uploads/'+x.filename)}" alt="${esc(p.title)}" loading="lazy">`).join('')}</div></div><div class="detail-toolbar"><div><span class="status-dot"></span> Anúncio disponível</div><div class="toolbar-actions"><button class="mini-btn" onclick="shareProperty(event,${p.id})">↗ Compartilhar</button><button class="mini-btn" onclick="toggleFavorite(event,${p.id})">${state.favorites.has(p.id)?'♥ Salvo':'♡ Salvar'}</button><button class="mini-btn" onclick="toggleCompare(event,${p.id})">${state.compare.has(p.id)?'✓ Comparando':'＋ Comparar'}</button></div></div><div class="detail-grid"><section><div class="eyebrow">${p.purpose==='aluguel'?'ALUGUEL':'VENDA'} · ${esc(p.type)}</div><h1>${esc(p.title)}</h1><p class="detail-location">${esc(p.neighborhood)} · ${esc(p.city)}</p><div class="detail-price">${money(p.price)}${p.purpose==='aluguel'?'<small>/mês</small>':''}</div><div class="detail-specs"><b>${p.area||0} m²<small>Área</small></b><b>${p.bedrooms||0}<small>Quartos</small></b><b>${p.suites||0}<small>Suítes</small></b><b>${p.bathrooms||0}<small>Banheiros</small></b><b>${p.parking||0}<small>Vagas</small></b></div><div class="cost-strip"><div><span>Condomínio</span><strong>${money(p.condo||0)}</strong></div><div><span>IPTU</span><strong>${money(p.iptu||0)}</strong></div><div><span>Custos informados</span><strong>${money(totalMonthly)}</strong></div></div><div class="detail-section"><h2>Sobre este imóvel</h2><p>${esc(p.description||'Consulte a equipe para mais informações sobre este imóvel.')}</p></div><div class="detail-section"><h2>Características</h2><div class="chips">${p.features.map(x=>`<span>${esc(x)}</span>`).join('')||'<span>Consulte a equipe</span>'}</div></div><div class="detail-section"><div class="section-head"><h2>Localização</h2><a class="text-btn" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${mapQuery}">Abrir no mapa →</a></div><div class="map-large real-map-card"><div class="map-grid"></div><div><span>LOCALIZAÇÃO</span><strong>${esc(p.neighborhood)}</strong><small>${esc(p.city)}</small></div></div></div></section><aside class="lead-card sticky-lead"><div class="eyebrow">ATENDIMENTO</div><h2>Quer conhecer este imóvel?</h2><p>Fale com a equipe, envie seu contato ou agende uma visita.</p><form onsubmit="sendLead(event,${p.id})"><input id="leadName" placeholder="Nome completo" value="${esc(state.user?.name||'')}" required><input id="leadWa" placeholder="WhatsApp" value="${esc(state.user?.phone||'')}" required><input id="leadEmail" type="email" placeholder="E-mail" value="${esc(state.user?.email||'')}"><textarea id="leadMsg" placeholder="O que você gostaria de saber?"></textarea><button class="btn btn-gold full">Tenho interesse</button></form><a class="btn btn-whatsapp full" target="_blank" rel="noopener" href="https://wa.me/${esc((state.settings.whatsapp||'').replace(/\D/g,''))}?text=${encodeURIComponent('Olá! Tenho interesse no imóvel: '+p.title)}">Falar no WhatsApp</a><button class="btn btn-light full" onclick="scheduleVisit(${p.id})">Agendar visita</button><button class="btn btn-light full" onclick="openChat(null,${p.id})">Falar pelo chat</button></aside></div>${related.length?`<section class="section related"><div class="section-head"><div><div class="eyebrow">OUTRAS OPÇÕES</div><h2>Você também pode gostar</h2></div></div><div class="property-grid">${related.map(propertyCard).join('')}</div></section>`:''}</div></main>`);}
async function sendLead(e,id){e.preventDefault();try{await api('/api/leads',{method:'POST',body:JSON.stringify({name:$("#leadName").value,whatsapp:$("#leadWa").value,email:$("#leadEmail").value,message:$("#leadMsg").value,property_id:id})});toast('Interesse enviado! A equipe entrará em contato.');e.target.reset()}catch(err){toast(err.message,'error')}}
async function toggleFavorite(e,id){if(e)e.stopPropagation();if(!state.user){openAuth('login');return}if(state.user.role!=="customer"){toast('Favoritos estão disponíveis para contas de cliente.','error');return}try{if(state.favorites.has(id)){await api('/api/me/favorites/'+id,{method:'DELETE'});state.favorites.delete(id);toast('Removido dos favoritos.')}else{await api('/api/me/favorites/'+id,{method:'POST'});state.favorites.add(id);toast('Salvo nos favoritos.')}$$(`.fav-btn[data-id="${id}"]`).forEach(b=>b.textContent=state.favorites.has(id)?'♥':'♡')}catch(err){toast(err.message,'error')}}
async function shareProperty(e,id){if(e)e.stopPropagation();const url=location.origin+'/#imovel/'+id;if(navigator.share)try{await navigator.share({title:'Imóvel no Imob Pro',url})}catch{}else{await navigator.clipboard?.writeText(url);toast('Link copiado.')}}
function empty(title,text){return `<div class="empty"><div class="empty-icon">⌂</div><h3>${title}</h3><p>${text}</p></div>`}
async function openQuickView(e,id){if(e)e.stopPropagation();const p=state.properties.find(x=>x.id===id)||await api('/api/properties/'+id);openModal(`<button class="close" onclick="closeModal()">×</button><div class="quick-view"><div class="quick-image"><img src="${esc(p.cover_image||'')}" alt="${esc(p.title)}"></div><div><div class="eyebrow">${p.purpose==='aluguel'?'ALUGUEL':'VENDA'} · ${esc(p.type)}</div><h2>${esc(p.title)}</h2><p class="detail-location">${esc(p.neighborhood)} · ${esc(p.city)}</p><div class="quick-price">${money(p.price)}${p.purpose==='aluguel'?'<small>/mês</small>':''}</div><div class="specs quick-specs"><span>${p.bedrooms} quartos</span><span>${p.bathrooms} ban.</span><span>${p.parking} vagas</span><span>${p.area} m²</span></div><p class="quick-description">${esc((p.description||'').slice(0,260))}${(p.description||'').length>260?'…':''}</p><div class="modal-actions"><button class="btn btn-light" onclick="toggleCompare(event,${p.id})">${state.compare.has(p.id)?'✓ Comparando':'＋ Comparar'}</button><button class="btn btn-gold" onclick="closeModal();openProperty(${p.id})">Abrir imóvel →</button></div></div></div>`)}
function toggleCompare(e,id){if(e)e.stopPropagation();if(state.compare.has(id)){state.compare.delete(id);toast('Removido da comparação.')}else{if(state.compare.size>=3){toast('Compare até 3 imóveis.','error');return}state.compare.add(id);toast('Imóvel adicionado à comparação.')}$$(`.property-card[data-property-card="${id}"] .mini-btn.selected`).forEach(b=>b.classList.remove('selected'));$$(`.property-card[data-property-card="${id}"] .mini-btn`).forEach(b=>{if(b.textContent.includes('Comparando')||b.textContent.includes('Comparar'))b.textContent=state.compare.has(id)?'✓ Comparando':'＋ Comparar';if(state.compare.has(id))b.classList.add('selected')});if(state.compare.size)toast(`${state.compare.size} imóvel(is) na comparação.`)}
function chatLauncher(){if(!state.user)return `<button class="chat-launcher" onclick="openChat()" aria-label="Entrar no chat"><span>◌</span><b>Falar com a equipe</b></button>`;return `<button class="chat-launcher" onclick="openChat()" aria-label="Abrir mensagens"><span>◌</span><b>Chat</b><i id="chatBadge" hidden></i></button>`}
async function openChat(withId=null,propertyId=null){if(!state.user){openAuth('login');return}state.chat.open=true;state.chat.contacts=await api('/api/messages/contacts');if(!state.chat.contacts.length){toast('Nenhum atendente disponível no momento.','error');return}state.chat.with=Number(withId)||state.chat.with||state.chat.contacts[0].id;renderChat(propertyId);startChatPolling()}
async function renderChat(propertyId=null){if(!state.chat.open)return;const c=state.chat.contacts.find(x=>x.id===state.chat.with)||state.chat.contacts[0];if(!c)return;const messages=await api('/api/messages?with='+c.id);const unread=await api('/api/messages/unread');const root=document.getElementById('chatRoot');if(!root)return;root.innerHTML=`<div class="chat-backdrop" onclick="closeChat()"></div><section class="chat-window" aria-label="Chat"><header class="chat-head"><div><span class="eyebrow">ATENDIMENTO</span><strong>${esc(c.name)}</strong><small>${c.role==='agent'?'Corretor':'Equipe Imob Pro'}</small></div><button onclick="closeChat()">×</button></header><div class="chat-layout"><aside class="chat-contacts">${state.chat.contacts.map(x=>`<button class="chat-contact ${x.id===c.id?'active':''}" onclick="selectChat(${x.id})"><span class="avatar">${esc((x.name||'?')[0])}</span><span><b>${esc(x.name)}</b><small>${x.role==='agent'?'Corretor':'Equipe'}</small></span></button>`).join('')}</aside><div class="chat-main"><div id="chatMessages" class="chat-messages">${messages.map(m=>`<div class="chat-message ${m.sender_id===state.user.id?'mine':'theirs'}"><div>${esc(m.body)}</div><small>${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||`<div class="chat-empty"><strong>Comece a conversa.</strong><span>Envie uma mensagem para a equipe.</span></div>`}</div><form class="chat-form" onsubmit="sendChatMessage(event,${c.id},${propertyId||'null'})"><textarea id="chatInput" maxlength="2000" rows="1" placeholder="Escreva sua mensagem…" required></textarea><button class="btn btn-gold">Enviar</button></form></div></div></section>`;requestAnimationFrame(()=>{const box=document.getElementById('chatMessages');if(box)box.scrollTop=box.scrollHeight;const input=document.getElementById('chatInput');if(input)input.focus()});const badge=document.getElementById('chatBadge');if(badge){badge.hidden=unread.count<1;badge.textContent=unread.count>9?'9+':unread.count}}
async function selectChat(id){state.chat.with=id;await renderChat();}
async function sendChatMessage(e,recipientId,propertyId=null){e.preventDefault();const input=document.getElementById('chatInput');const body=input?.value.trim();if(!body)return;try{await api('/api/messages',{method:'POST',body:JSON.stringify({recipient_id:recipientId,body,property_id:propertyId})});input.value='';await renderChat(propertyId)}catch(err){toast(err.message,'error')}}
function closeChat(){state.chat.open=false;if(state.chat.poll){clearInterval(state.chat.poll);state.chat.poll=null}const r=document.getElementById('chatRoot');if(r)r.innerHTML=''}
async function refreshChatMessages(){if(!state.chat.open||!state.chat.with)return;try{const messages=await api('/api/messages?with='+state.chat.with);const box=document.getElementById('chatMessages');if(!box)return;const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<80;box.innerHTML=messages.map(m=>`<div class="chat-message ${m.sender_id===state.user.id?'mine':'theirs'}"><div>${esc(m.body)}</div><small>${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||`<div class="chat-empty"><strong>Comece a conversa.</strong><span>Envie uma mensagem para a equipe.</span></div>`;if(nearBottom)box.scrollTop=box.scrollHeight;refreshChatBadge()}catch{}}
function startChatPolling(){if(state.chat.poll)clearInterval(state.chat.poll);state.chat.poll=setInterval(refreshChatMessages,5000)}


function runHomeSearch(){location.hash='buscar';searchPage(null,state.filters.purpose,$("#homeType").value)}
function quickSearch(p,t){state.filters={purpose:p,type:t};searchPage(null,p,t)}
async function saveCurrentSearch(){if(!state.user){openAuth('register');return}const name=prompt('Nome para esta busca:','Minha busca');if(!name)return;await api('/api/me/saved-searches',{method:'POST',body:JSON.stringify({name,filters:state.filters})});toast('Busca salva.')}
function openMenu(){alert('No celular, use Entrar para acessar sua conta. O menu completo fica disponível na navegação principal.')}
function ownerInfo(e){if(e)e.preventDefault();$("#site").innerHTML=shell(`<main class="owner-landing"><div class="container owner-hero"><div><div class="eyebrow">PARA PROPRIETÁRIOS</div><h1>Coloque seu imóvel em uma experiência profissional.</h1><p>Cadastre seus dados, envie o anúncio para análise e acompanhe tudo pelo seu portal.</p><button class="btn btn-dark" onclick="openAuth('registerOwner')">Criar acesso de anunciante</button></div><div class="owner-panel"><span>PORTAL</span><strong>Meus imóveis</strong><div class="fake-row">Apartamento · Publicado <b>42 views</b></div><div class="fake-row">Casa · Em análise <b>12 views</b></div></div></div></main>`);return false}
function openAuth(mode='login'){const register=mode==='register'||mode==='registerOwner';$("#modalRoot").innerHTML=`<div class="modal"><div class="modal-card auth-card"><button class="close" onclick="closeModal()">×</button><div class="eyebrow">IMOB PRO</div><h2>${register?'Criar conta':'Bem-vindo de volta'}</h2><p>${register?'Cadastre sua conta em poucos passos.':'Entre para acessar favoritos, buscas e seu painel.'}</p><form onsubmit="submitAuth(event,'${register?'register':'login'}',${mode==='registerOwner'})">${register?'<input id="authName" placeholder="Nome completo" required><input id="authPhone" placeholder="WhatsApp"><input id="authEmail" type="email" placeholder="E-mail" required><input id="authPass" type="password" placeholder="Senha (mín. 6 caracteres)" minlength="6" required>':'<input id="authEmail" type="email" placeholder="E-mail" required><input id="authPass" type="password" placeholder="Senha" required>'}<button class="btn btn-gold full">${register?'Criar conta':'Entrar'}</button></form><button class="link-btn" onclick="forgotPassword()">Esqueci minha senha</button><button class="link-btn" onclick="openAuth('${register?'login':'register'}')">${register?'Já tenho uma conta':'Criar uma conta'}</button></div></div>`}
async function submitAuth(e,type,owner){e.preventDefault();try{let d;if(type==='login')d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$("#authEmail").value,password:$("#authPass").value})});else{d=await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:$("#authName").value,email:$("#authEmail").value,password:$("#authPass").value,phone:$("#authPhone").value})});if(owner){await api('/api/auth/logout',{method:'POST'});toast('Conta de cliente criada. Um administrador deve criar o acesso de anunciante.');return}}state.user=d;closeModal();await loadFavorites();if(d.role==='agent')agentDashboard();else if(d.role==='admin'||d.role==='manager'||d.role==='editor')adminDashboard();else if(d.role==='owner')ownerDashboard();else customerDashboard()}catch(err){toast(err.message,'error')}}
async function forgotPassword(){const email=prompt('Digite seu e-mail:');if(!email)return;const r=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify({email})});toast(r.message)}
function closeModal(){$("#modalRoot").innerHTML=""}
function openModal(html){$("#modalRoot").innerHTML=`<div class="modal"><div class="modal-card">${html}</div></div>`}
async function account(section){if(!state.user){openAuth();return}if(state.user.role==='customer')return customerDashboard(section);if(state.user.role==='agent')return agentDashboard();if(state.user.role==='owner')return ownerDashboard();return adminDashboard()}
async function customerDashboard(section='favorites'){const favs=await api('/api/me/favorites');const saved=await api('/api/me/saved-searches');const cols=await api('/api/me/collections');const ns=await api('/api/me/notifications');let content='';if(section==='saved')content=saved.map(x=>`<div class="dash-card"><b>${esc(x.name)}</b><p>${esc(x.frequency)} · ${new Date(x.created_at).toLocaleDateString('pt-BR')}</p><button class="mini-btn" onclick="deleteSaved(${x.id})">Excluir</button></div>`).join('')||empty('Nenhuma busca salva','Salve uma pesquisa para receber novos resultados.');else if(section==='collections')content=cols.map(c=>`<div class="dash-card"><h3>${esc(c.name)}</h3><p>${esc(c.description||'Coleção de imóveis')}</p><div class="mini-grid">${(c.items||[]).map(propertyCard).join('')||'<small>Nenhum imóvel nesta coleção.</small>'}</div></div>`).join('')||empty('Nenhuma coleção','Crie uma coleção para organizar seus imóveis.');else if(section==='notifications')content=ns.map(n=>`<div class="activity-row ${n.read_at?'':'unread'}"><span class="avatar">♢</span><div><b>${esc(n.title)}</b><p>${esc(n.message)}</p></div><button class="mini-btn" onclick="readNotification(${n.id})">${n.read_at?'Lida':'Marcar como lida'}</button></div>`).join('')||empty('Tudo em dia','Você não tem notificações.');else content=`<div class="property-grid">${favs.map(propertyCard).join('')||empty('Nenhum favorito ainda','Explore os imóveis e salve os que você gostar.')}</div>`;document.querySelector('#site').innerHTML=appShell('Minha conta',`<div class="account-head"><div><div class="eyebrow">ÁREA DO CLIENTE</div><h1>Olá, ${esc(state.user.name.split(' ')[0])}.</h1><p>Seus imóveis, buscas e atividades em um só lugar.</p></div><button class="btn btn-light" onclick="logout()">Sair</button></div><div class="metric-row four"><div><b>${favs.length}</b><span>Favoritos</span></div><div><b>${saved.length}</b><span>Buscas salvas</span></div><div><b>${cols.length}</b><span>Coleções</span></div><div><b>${ns.filter(x=>!x.read_at).length}</b><span>Não lidas</span></div></div><div class="tabs-panel"><button class="${section==='favorites'?'active':''}" onclick="customerDashboard('favorites')">Favoritos</button><button class="${section==='saved'?'active':''}" onclick="customerDashboard('saved')">Buscas salvas</button><button class="${section==='collections'?'active':''}" onclick="customerDashboard('collections')">Coleções</button><button class="${section==='notifications'?'active':''}" onclick="customerDashboard('notifications')">Notificações</button></div>${content}`)}
async function deleteSaved(id){try{await api('/api/me/saved-searches/'+id,{method:'DELETE'});toast('Busca removida.');customerDashboard('saved')}catch(e){toast(e.message,'error')}}
async function readNotification(id){try{await api('/api/me/notifications/'+id+'/read',{method:'PATCH'});customerDashboard('notifications')}catch(e){toast(e.message,'error')}}

function appShell(title,body){const r=state.user?.role;const isStaff=["admin","manager","editor"].includes(r);const isAgent=r==='agent';const isOwner=r==='owner';let nav='';if(isAgent){nav=`<div class="side-label">ATENDIMENTO</div><button onclick="agentDashboard()">⌂ Visão geral</button><button onclick="openChat()">◌ Conversas <span class="nav-chat-badge" id="sideChatBadge" hidden></span></button><button onclick="agentLeads()">◎ Meus leads</button><button onclick="agentTasks()">✓ Minhas tarefas</button><div class="side-label">EXPLORAR</div><button onclick="searchPage(event,'')">⌕ Imóveis</button>`}else if(isStaff){nav=`<div class="side-label">VISÃO GERAL</div><button onclick="adminDashboard()">⌂ Dashboard</button><button onclick="searchPage(event,'')">⌕ Explorar imóveis</button><div class="side-label">CRM</div><button onclick="adminLeads()">◎ Leads</button><button onclick="adminClients()">♙ Clientes</button><button onclick="adminVisits()">◷ Visitas</button><button onclick="adminTasks()">✓ Tarefas</button><button onclick="openChat()">◌ Mensagens <span class="nav-chat-badge" id="sideChatBadge" hidden></span></button><div class="side-label">GESTÃO</div><button onclick="adminProperties()">▣ Imóveis</button><button onclick="adminOwners()">♙ Anunciantes</button><button onclick="adminAttendants()">◉ Atendentes</button><button onclick="adminAutomations()">⚙ Automações</button><button onclick="adminPrivacyRequests()">◇ Privacidade</button><button onclick="adminActivity()">◌ Auditoria</button>`}else if(isOwner){nav=`<div class="side-label">PORTAL</div><button onclick="ownerDashboard()">⌂ Meus imóveis</button><button onclick="openChat()">◌ Atendimento <span class="nav-chat-badge" id="sideChatBadge" hidden></span></button><button onclick="searchPage(event,'')">⌕ Explorar imóveis</button>`}else{nav=`<div class="side-label">MINHA JORNADA</div><button onclick="customerDashboard('favorites')">♡ Favoritos</button><button onclick="customerDashboard('saved')">⌁ Buscas salvas</button><button onclick="customerDashboard('collections')">▤ Coleções</button><button onclick="customerDashboard('notifications')">♢ Notificações</button><button onclick="openChat()">◌ Falar com a equipe <span class="nav-chat-badge" id="sideChatBadge" hidden></span></button>`}return `<div class="app-layout"><aside class="app-sidebar"><a class="brand" href="#" onclick="return home(event)"><span class="brand-mark">I</span>Imob Pro</a>${nav}<div class="side-label">CONTA</div><button onclick="profileModal()">◎ Meu perfil</button><button onclick="logout()">↪ Sair</button></aside><main class="app-main"><div class="app-mobile-head"><a class="brand" href="#" onclick="return home(event)"><span class="brand-mark">I</span>Imob Pro</a><div class="mobile-nav-actions"><button onclick="profileModal()">◎</button><button onclick="logout()">↪</button></div></div><div class="container app-content">${body}</div></main></div><div class="chat-admin-launch">${isAgent||isStaff||isOwner?`<button class="chat-launcher" onclick="openChat()" aria-label="Abrir mensagens"><span>◌</span><b>${isAgent?'Conversas':'Mensagens'}</b><i id="chatBadge" hidden></i></button>`:''}</div><div id="chatRoot"></div>`}

async function agentDashboard(){const s=await api('/api/agent/summary');const leads=await api('/api/agent/leads');const tasks=await api('/api/agent/tasks');$("#site").innerHTML=appShell('Atendimento',`<div class="account-head"><div><div class="eyebrow">ATENDIMENTO · ${esc(state.user.name)}</div><h1>Sua central.</h1><p>Converse com clientes, acompanhe seus leads e organize suas próximas ações.</p></div><div class="top-actions"><button class="btn btn-gold" onclick="openChat()">◌ Abrir conversas</button></div></div><div class="metric-row four"><div><b>${s.openLeads}</b><span>Leads em atendimento</span></div><div><b>${s.leads}</b><span>Meus leads</span></div><div><b>${s.tasks}</b><span>Tarefas abertas</span></div><div><b>${s.unread}</b><span>Mensagens novas</span></div></div><div class="dashboard-grid"><section class="dash-card"><div class="dash-title"><h2>Leads recentes</h2><button class="text-btn" onclick="agentLeads()">Ver todos →</button></div>${leads.slice(0,5).map(l=>`<div class="activity-row"><span class="avatar">${esc((l.name||'?')[0])}</span><div><b>${esc(l.name)}</b><p>${esc(l.property_title||'Sem imóvel')} · ${esc(l.whatsapp)}</p></div><button class="mini-btn" onclick="openChat(${l.customer_id||0},${l.property_id||'null'})">Conversar</button></div>`).join('')||empty('Nenhum lead atribuído','Quando um lead for atribuído a você, ele aparecerá aqui.')}</section><section class="dash-card"><div class="dash-title"><h2>Próximas tarefas</h2><button class="text-btn" onclick="agentTasks()">Ver todas →</button></div>${tasks.filter(t=>t.status==='open').slice(0,5).map(t=>`<div class="activity-row"><span class="avatar">✓</span><div><b>${esc(t.title)}</b><p>${esc(t.lead_name||t.property_title||'Sem vínculo')} · ${t.due_at?new Date(t.due_at).toLocaleString('pt-BR'):'Sem prazo'}</p></div><button class="mini-btn" onclick="finishAgentTask(${t.id})">Concluir</button></div>`).join('')||empty('Sem tarefas','Você está em dia.')}</section></div>`);refreshChatBadge()}
async function agentLeads(){const leads=await api('/api/agent/leads');$("#site").innerHTML=appShell('Meus leads',`<div class="account-head"><div><div class="eyebrow">ATENDIMENTO</div><h1>Meus leads.</h1><p>Somente os leads atribuídos a você.</p></div><button class="btn btn-gold" onclick="openChat()">◌ Conversas</button></div><div class="admin-list">${leads.map(l=>`<div class="admin-property-row"><div class="avatar large">${esc((l.name||'?')[0])}</div><div class="grow"><b>${esc(l.name)}</b><p>${esc(l.whatsapp)} · ${esc(l.property_title||'Sem imóvel')}</p><small>${esc(l.message||'Sem mensagem')}</small></div><span class="status ${l.status==='closed'?'published':'pending'}">${statusLabel[l.status]||l.status}</span><button class="mini-btn" onclick="openChat(${l.customer_id||0},${l.property_id||'null'})">Conversar</button></div>`).join('')||empty('Nenhum lead','Novos leads atribuídos aparecerão aqui.')}</div>`);refreshChatBadge()}
async function agentTasks(){const tasks=await api('/api/agent/tasks');$("#site").innerHTML=appShell('Minhas tarefas',`<div class="account-head"><div><div class="eyebrow">ATENDIMENTO</div><h1>Minhas tarefas.</h1><p>Próximas ações atribuídas a você.</p></div></div><div class="admin-list">${tasks.map(t=>`<div class="admin-property-row"><div class="grow"><b>${esc(t.title)}</b><p>${esc(t.lead_name||t.property_title||'Sem vínculo')} · ${t.due_at?new Date(t.due_at).toLocaleString('pt-BR'):'Sem prazo'}</p><small>${esc(t.notes||'')}</small></div><span class="status ${t.status==='open'?'pending':'published'}">${t.status==='open'?'Aberta':'Concluída'}</span>${t.status==='open'?`<button class="mini-btn" onclick="finishAgentTask(${t.id})">Concluir</button>`:''}</div>`).join('')||empty('Sem tarefas','Você está em dia.')}</div>`);refreshChatBadge()}
async function finishAgentTask(id){try{await api('/api/agent/tasks/'+id,{method:'PATCH',body:JSON.stringify({status:'done'})});toast('Tarefa concluída.');agentTasks()}catch(e){toast(e.message,'error')}}

async function adminDashboard(){const s=await api('/api/admin/stats');const leads=await api('/api/admin/leads');const props=await api('/api/admin/properties');$("#site").innerHTML=appShell('Dashboard',`<div class="account-head"><div><div class="eyebrow">${esc(state.user.role.toUpperCase())} · CRM</div><h1>Visão geral.</h1><p>A operação da sua imobiliária, organizada.</p></div><div class="top-actions"><button class="btn btn-light" onclick="adminProperties()">＋ Novo imóvel</button><button class="btn btn-gold" onclick="adminOwnerForm()">＋ Anunciante</button></div></div><div class="metric-row four"><div><b>${s.properties}</b><span>Imóveis</span></div><div><b>${s.newLeads}</b><span>Leads novos</span></div><div><b>${s.visits}</b><span>Visitas agendadas</span></div><div><b>${s.customers}</b><span>Clientes</span></div></div><div class="dashboard-grid"><section class="dash-card"><div class="dash-title"><h2>Pipeline de leads</h2><button class="text-btn" onclick="adminLeads()">Ver todos →</button></div><div class="pipeline-mini">${['new','contacted','qualified','visit','proposal','negotiation'].map(st=>`<div><span>${statusLabel[st]}</span><strong>${leads.filter(x=>x.status===st).length}</strong></div>`).join('')}</div></section><section class="dash-card"><div class="dash-title"><h2>Atividade recente</h2><button class="text-btn" onclick="adminActivity()">Histórico →</button></div>${leads.slice(0,5).map(l=>`<div class="activity-row"><span class="avatar">${esc(l.name[0])}</span><div><b>${esc(l.name)}</b><p>Interesse em ${esc(l.property_title||'um imóvel')}</p></div><small>${new Date(l.created_at).toLocaleDateString('pt-BR')}</small></div>`).join('')||empty('Sem atividade','Novos leads aparecerão aqui.')}</section></div><section class="dash-card"><div class="dash-title"><h2>Imóveis recentes</h2><button class="text-btn" onclick="adminProperties()">Gerenciar →</button></div><div class="admin-list">${props.slice(0,5).map(p=>`<div class="admin-property-row"><img src="${esc(p.cover_image||'')}" alt=""><div><b>${esc(p.title)}</b><p>${esc(p.neighborhood)} · ${money(p.price)}</p></div><span class="status ${p.status}">${statusLabel[p.status]||p.status}</span><button class="mini-btn" onclick="editAdminProperty(${p.id})">Editar</button></div>`).join('')}</div></section>`)}
async function adminProperties(){const ps=await api('/api/admin/properties');$("#site").innerHTML=appShell('Imóveis',`<div class="account-head"><div><div class="eyebrow">CATÁLOGO</div><h1>Imóveis.</h1><p>${ps.length} registros na plataforma.</p></div><button class="btn btn-gold" onclick="adminPropertyForm()">＋ Novo imóvel</button></div><div class="toolbar"><input id="adminSearch" placeholder="Buscar imóvel..." oninput="filterAdminProperties()"><select id="adminStatus" onchange="filterAdminProperties()"><option value="">Todos os status</option>${Object.entries(statusLabel).filter(([k])=>['draft','pending','published','paused','sold','rented','archived'].includes(k)).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div id="adminPropList" class="admin-list">${ps.map(adminPropertyRow).join('')}</div>`)}
function adminPropertyRow(p){return `<div class="admin-property-row"><img src="${esc(p.cover_image||'')}" alt=""><div class="grow"><b>${esc(p.title)}</b><p>${esc(p.neighborhood)} · ${esc(p.city)} · ${money(p.price)}</p><small>Proprietário: ${esc(p.owner_name||'Imobiliária')}</small></div><select class="status-select" onchange="changePropertyStatus(${p.id},this.value)">${['draft','pending','published','paused','sold','rented','archived'].map(x=>`<option value="${x}" ${p.status===x?'selected':''}>${statusLabel[x]}</option>`).join('')}</select><button class="mini-btn" onclick="editAdminProperty(${p.id})">Editar</button></div>`}
async function filterAdminProperties(){const ps=await api('/api/admin/properties');const q=$("#adminSearch").value.toLowerCase(),st=$("#adminStatus").value;$("#adminPropList").innerHTML=ps.filter(p=>(!q||p.title.toLowerCase().includes(q)||p.neighborhood.toLowerCase().includes(q))&&(!st||p.status===st)).map(adminPropertyRow).join('')||empty('Nenhum imóvel','Ajuste os filtros.')}
async function changePropertyStatus(id,status){try{await api('/api/admin/properties/'+id+'/status',{method:'PATCH',body:JSON.stringify({status})});toast('Status atualizado.')}catch(e){toast(e.message,'error')}}
function adminPropertyForm(p=null){const x=p||{};const imgs=x.images||[];openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">CADASTRO DE IMÓVEL</div><h2>${p?'Editar imóvel':'Novo imóvel'}</h2><p class="modal-subtitle">Cadastre apenas as informações usadas no anúncio e envie as fotos diretamente do computador, celular ou tablet.</p><form onsubmit="saveAdminProperty(event,${p?.id||0})"><div class="form-grid"><input id="pfTitle" placeholder="Título do anúncio" value="${esc(x.title||'')}" required class="wide"><select id="pfType"><option ${x.type==='Apartamento'?'selected':''}>Apartamento</option><option ${x.type==='Casa'?'selected':''}>Casa</option><option ${x.type==='Comercial'?'selected':''}>Comercial</option><option ${x.type==='Terreno'?'selected':''}>Terreno</option></select><select id="pfPurpose"><option value="venda" ${x.purpose==='venda'||!p?'selected':''}>Venda</option><option value="aluguel" ${x.purpose==='aluguel'?'selected':''}>Aluguel</option></select><input id="pfPrice" type="number" min="0" step="0.01" placeholder="Preço" value="${x.price||''}" required><input id="pfArea" type="number" min="0" step="0.01" placeholder="Área m²" value="${x.area||''}"><input id="pfCity" placeholder="Cidade" value="${esc(x.city||'Fortaleza')}" required><input id="pfNeighborhood" placeholder="Bairro" value="${esc(x.neighborhood||'')}" required><input id="pfBedrooms" type="number" min="0" placeholder="Quartos" value="${x.bedrooms||0}"><input id="pfSuites" type="number" min="0" placeholder="Suítes" value="${x.suites||0}"><input id="pfBathrooms" type="number" min="0" placeholder="Banheiros" value="${x.bathrooms||0}"><input id="pfParking" type="number" min="0" placeholder="Vagas" value="${x.parking||0}"><input id="pfCondo" type="number" min="0" step="0.01" placeholder="Condomínio" value="${x.condo||0}"><input id="pfIptu" type="number" min="0" step="0.01" placeholder="IPTU" value="${x.iptu||0}"><input id="pfAddress" placeholder="Endereço" value="${esc(x.address||'')}" class="wide"><textarea id="pfDescription" placeholder="Descrição do imóvel" class="wide">${esc(x.description||'')}</textarea><input id="pfFeatures" placeholder="Características: piscina, varanda, elevador..." value="${esc((x.features||[]).join(', '))}" class="wide"></div><section class="owner-photo-upload admin-photo-upload"><div class="upload-head"><div><div class="eyebrow">FOTOS DO IMÓVEL</div><h3>Adicione as fotos do anúncio.</h3><p>JPG, PNG ou WEBP · até 20 imagens por envio · 10 MB por imagem.</p></div><label class="upload-button"><input id="pfImages" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="previewAdminImages(event)">＋ Adicionar fotos</label></div><div id="adminImagePreview" class="image-preview-grid">${imgs.map((im,i)=>`<div class="image-preview"><img src="${esc(im.filename.startsWith('http')?im.filename:'/uploads/'+im.filename)}" alt="Foto ${i+1}" loading="lazy"><span>${i===0?'Capa':'Foto'}</span></div>`).join('')}</div><div id="adminImageHint" class="form-note">${imgs.length?`${imgs.length} foto(s) já cadastrada(s). Você pode adicionar novas fotos.`:'Nenhuma foto adicionada ainda. Recomendamos pelo menos 5 fotos.'}</div></section><div class="modal-actions"><button type="button" class="btn btn-light" onclick="closeModal()">Cancelar</button><button class="btn btn-gold" id="adminSaveBtn">${p?'Salvar alterações':'Salvar imóvel'}</button></div></form>`)}
function previewAdminImages(e){const files=[...(e.target.files||[])];const wrap=$('#adminImagePreview');if(!wrap)return;const existing=wrap.querySelectorAll('.image-preview:not(.pending)').length;wrap.querySelectorAll('.image-preview.pending').forEach(x=>x.remove());files.forEach((f,i)=>{const src=URL.createObjectURL(f);const div=document.createElement('div');div.className='image-preview pending';div.innerHTML=`<img src="${src}" alt="Prévia ${i+1}"><span>${existing===0&&i===0?'Nova capa':'Nova foto'}</span>`;wrap.appendChild(div)});$('#adminImageHint').textContent=files.length?`${files.length} foto(s) selecionada(s). Elas serão enviadas ao salvar o imóvel.`:`${existing} foto(s) já cadastrada(s).`}
async function uploadAdminImages(id,files){if(!files?.length)return null;const form=new FormData();files.forEach(f=>form.append('images',f));return api('/api/admin/properties/'+id+'/images',{method:'POST',body:form})}
async function editAdminProperty(id){const p=await api('/api/properties/'+id);adminPropertyForm(p)}
async function saveAdminProperty(e,id){e.preventDefault();const btn=$('#adminSaveBtn');const files=[...($('#pfImages')?.files||[])];const b={title:$("#pfTitle").value,type:$("#pfType").value,purpose:$("#pfPurpose").value,price:$("#pfPrice").value,area:$("#pfArea").value,city:$("#pfCity").value,neighborhood:$("#pfNeighborhood").value,bedrooms:$("#pfBedrooms").value,suites:$("#pfSuites").value,bathrooms:$("#pfBathrooms").value,parking:$("#pfParking").value,condo:$("#pfCondo").value,iptu:$("#pfIptu").value,address:$("#pfAddress").value,description:$("#pfDescription").value,features:$("#pfFeatures").value.split(',').map(x=>x.trim()).filter(Boolean)};try{btn.disabled=true;btn.textContent=files.length?'Salvando e enviando fotos…':'Salvando…';const saved=await api(id?'/api/admin/properties/'+id:'/api/admin/properties',{method:id?'PATCH':'POST',body:JSON.stringify(b)});const propertyId=saved.property?.id||saved.id||id;if(files.length)await uploadAdminImages(propertyId,files);closeModal();toast(files.length?`Imóvel salvo com ${files.length} foto(s).`:'Imóvel salvo.');adminProperties()}catch(err){btn.disabled=false;btn.textContent=id?'Salvar alterações':'Salvar imóvel';toast(err.message,'error')}}
async function adminClients(){const us=await api('/api/admin/users');const clients=us.filter(u=>u.role==='customer');document.querySelector('#site').innerHTML=appShell('Clientes',`<div class="account-head"><div><div class="eyebrow">CRM · CLIENTES</div><h1>Clientes.</h1><p>${clients.length} contas cadastradas na plataforma.</p></div></div><div class="admin-list">${clients.map(u=>`<div class="admin-property-row"><div class="avatar large">${esc((u.name||'?')[0])}</div><div class="grow"><b>${esc(u.name)}</b><p>${esc(u.email)} · ${esc(u.phone||'Sem telefone')}</p></div><button class="mini-btn" onclick="profileClient(${u.id})">Ver perfil</button></div>`).join('')||empty('Nenhum cliente','Os clientes cadastrados pelo site aparecerão aqui.')}</div>`)}
async function profileClient(id){const us=await api('/api/admin/users');const u=us.find(x=>x.id===id);if(!u)return;openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">CLIENTE</div><h2>${esc(u.name)}</h2><p>${esc(u.email)}</p><p>${esc(u.phone||'Sem telefone cadastrado')}</p><div class="form-note">A conta e as credenciais permanecem persistidas no banco. A senha nunca é exibida: apenas seu hash seguro é armazenado.</div>`)}
async function adminVisits(){const vs=await api('/api/admin/visits');document.querySelector('#site').innerHTML=appShell('Visitas',`<div class="account-head"><div><div class="eyebrow">AGENDA</div><h1>Visitas.</h1><p>Visitas solicitadas e agendadas.</p></div><button class="btn btn-gold" onclick="adminVisitForm()">＋ Nova visita</button></div><div class="admin-list">${vs.map(v=>`<div class="admin-property-row"><div class="avatar large">◷</div><div class="grow"><b>${esc(v.property_title||'Imóvel')}</b><p>${esc(v.lead_name||'Cliente')} · ${new Date(v.visit_date).toLocaleString('pt-BR')}</p></div><span class="status ${v.status==='scheduled'?'published':''}">${esc(v.status)}</span></div>`).join('')||empty('Agenda vazia','As visitas solicitadas aparecerão aqui.')}</div>`)}
function adminVisitForm(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">AGENDA</div><h2>Nova visita</h2><form onsubmit="saveVisit(event)"><input id="vfProperty" type="number" placeholder="ID do imóvel" required><input id="vfCustomer" type="number" placeholder="ID do cliente"><input id="vfDate" type="datetime-local" required><textarea id="vfNotes" placeholder="Observações"></textarea><button class="btn btn-gold full">Agendar visita</button></form>`)}
async function saveVisit(e){e.preventDefault();try{await api('/api/admin/visits',{method:'POST',body:JSON.stringify({property_id:Number($('#vfProperty').value),customer_id:Number($('#vfCustomer').value)||null,visit_date:$('#vfDate').value,notes:$('#vfNotes').value})});closeModal();toast('Visita agendada.');adminVisits()}catch(err){toast(err.message,'error')}}
async function adminTasks(){const ts=await api('/api/admin/tasks');document.querySelector('#site').innerHTML=appShell('Tarefas',`<div class="account-head"><div><div class="eyebrow">OPERAÇÃO</div><h1>Tarefas.</h1><p>Próximas ações da equipe.</p></div><button class="btn btn-gold" onclick="adminTaskForm()">＋ Nova tarefa</button></div><div class="admin-list">${ts.map(t=>`<div class="admin-property-row"><div class="grow"><b>${esc(t.title)}</b><p>${esc(t.lead_name||'Sem lead')} · ${t.due_at?new Date(t.due_at).toLocaleString('pt-BR'):'Sem prazo'}</p></div><span class="status ${t.status==='open'?'pending':'published'}">${esc(t.status)}</span><button class="mini-btn" onclick="finishTask(${t.id})">${t.status==='open'?'Concluir':'Reabrir'}</button></div>`).join('')||empty('Sem tarefas','Crie uma tarefa para começar.')}</div>`)}
function adminTaskForm(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">OPERAÇÃO</div><h2>Nova tarefa</h2><form onsubmit="saveTask(event)"><input id="tfTitle" placeholder="Título" required><input id="tfDue" type="datetime-local"><select id="tfPriority"><option value="normal">Normal</option><option value="high">Alta</option><option value="low">Baixa</option></select><textarea id="tfNotes" placeholder="Observações"></textarea><button class="btn btn-gold full">Criar tarefa</button></form>`)}
async function saveTask(e){e.preventDefault();try{await api('/api/admin/tasks',{method:'POST',body:JSON.stringify({title:$('#tfTitle').value,due_at:$('#tfDue').value,priority:$('#tfPriority').value,notes:$('#tfNotes').value})});closeModal();toast('Tarefa criada.');adminTasks()}catch(err){toast(err.message,'error')}}
async function finishTask(id){try{await api('/api/admin/tasks/'+id,{method:'PATCH',body:JSON.stringify({status:'done'})});toast('Tarefa atualizada.');adminTasks()}catch(err){toast(err.message,'error')}}
async function adminLeads(){const leads=await api('/api/admin/leads');$("#site").innerHTML=appShell('Leads',`<div class="account-head"><div><div class="eyebrow">CRM</div><h1>Leads.</h1><p>Todos os contatos captados pela plataforma.</p></div><button class="btn btn-light" onclick="adminDashboard()">← Dashboard</button></div><div class="pipeline-board">${['new','contacted','qualified','visit','proposal','negotiation','closed'].map(st=>`<section><div class="column-head"><span>${statusLabel[st]}</span><b>${leads.filter(l=>l.status===st).length}</b></div>${leads.filter(l=>l.status===st).map(l=>`<article class="lead-card"><b>${esc(l.name)}</b><p>${esc(l.property_title||'Sem imóvel')}</p><small>${esc(l.whatsapp)}</small><select onchange="changeLead(${l.id},this.value)">${['new','contacted','qualified','visit','proposal','negotiation','closed','lost'].map(x=>`<option value="${x}" ${x===l.status?'selected':''}>${statusLabel[x]}</option>`).join('')}</select></article>`).join('')||'<div class="column-empty">Nenhum</div>'}</section>`).join('')}</div>`)}
async function changeLead(id,status){try{await api('/api/admin/leads/'+id,{method:'PATCH',body:JSON.stringify({status})});toast('Lead atualizado.');adminLeads()}catch(e){toast(e.message,'error')}}
async function adminOwners(){const us=await api('/api/admin/users');const owners=us.filter(u=>u.role==='owner');$("#site").innerHTML=appShell('Anunciantes',`<div class="account-head"><div><div class="eyebrow">PROPRIETÁRIOS</div><h1>Anunciantes.</h1><p>${owners.length} acessos de proprietários.</p></div><button class="btn btn-gold" onclick="adminOwnerForm()">＋ Novo anunciante</button></div><div class="admin-list">${owners.map(u=>`<div class="admin-property-row"><div class="avatar large">${esc(u.name[0])}</div><div class="grow"><b>${esc(u.name)}</b><p>${esc(u.email)} · ${esc(u.phone||'sem telefone')}</p></div><span class="status published">Ativo</span></div>`).join('')||empty('Nenhum anunciante','Crie o primeiro acesso para um proprietário.')}</div>`)}
async function adminAttendants(){const us=await api('/api/admin/users');const staff=us.filter(u=>['agent','manager','admin'].includes(u.role));const attendants=staff.filter(u=>['agent','manager','admin'].includes(u.role));document.querySelector('#site').innerHTML=appShell('Atendentes',`<div class="account-head"><div><div class="eyebrow">ATENDIMENTO</div><h1>Atendentes.</h1><p>Gerencie quem pode receber e responder conversas no chat.</p></div><button class="btn btn-gold" onclick="adminAttendantForm()">＋ Adicionar atendente</button></div><div class="info-callout"><b>Como funciona</b><p>Clientes e anunciantes verão automaticamente os atendentes ativos aqui. Crie pelo menos um atendente para liberar o chat.</p></div><div class="admin-list">${attendants.map(u=>`<div class="admin-property-row"><div class="avatar large">${esc((u.name||'A')[0])}</div><div class="grow"><b>${esc(u.name)}</b><p>${esc(u.email)} · ${esc(u.phone||'sem telefone')}</p></div><span class="status published">${u.role==='agent'?'Atendente':u.role==='manager'?'Gerente':'Administrador'}</span></div>`).join('')||empty('Nenhum atendente cadastrado','Adicione um atendente para que os clientes possam iniciar conversas.')}</div>`)}
function adminAttendantForm(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">ATENDIMENTO</div><h2>Adicionar atendente</h2><p class="modal-subtitle">Esse acesso terá uma área própria de atendimento para conversar com clientes e acompanhar seus leads e tarefas.</p><form onsubmit="saveAttendant(event)"><input id="afName" placeholder="Nome completo" required><input id="afEmail" type="email" placeholder="E-mail profissional" required><input id="afPhone" placeholder="WhatsApp / telefone"><input id="afPass" type="password" placeholder="Senha inicial" minlength="6" required><button class="btn btn-gold full">Criar atendente</button></form>`)}
async function saveAttendant(e){e.preventDefault();try{await api('/api/admin/users',{method:'POST',body:JSON.stringify({name:$('#afName').value,email:$('#afEmail').value,phone:$('#afPhone').value,password:$('#afPass').value,role:'agent'})});closeModal();toast('Atendente adicionado. O chat já pode recebê-lo.');adminAttendants()}catch(err){toast(err.message,'error')}}
function adminOwnerForm(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">PORTAL DO ANUNCIANTE</div><h2>Novo anunciante</h2><form onsubmit="saveOwner(event)"><input id="ofName" placeholder="Nome completo" required><input id="ofEmail" type="email" placeholder="E-mail" required><input id="ofPhone" placeholder="WhatsApp"><input id="ofPass" type="password" placeholder="Senha inicial" minlength="6" required><button class="btn btn-gold full">Criar acesso</button></form>`)}
async function saveOwner(e){e.preventDefault();try{await api('/api/admin/users',{method:'POST',body:JSON.stringify({name:$("#ofName").value,email:$("#ofEmail").value,phone:$("#ofPhone").value,password:$("#ofPass").value,role:'owner'})});closeModal();toast('Acesso criado.');adminOwners()}catch(err){toast(err.message,'error')}}
async function ownerDashboard(){const ps=await api('/api/owner/properties');const photoCount=p=>Array.isArray(p.images)?p.images.length:(p.cover_image?1:0);const cards=ps.map(p=>`<article class="property-card compact"><div class="property-media"><img src="${esc(p.cover_image||'')}" alt="${esc(p.title)}" loading="lazy" width="900" height="620"><span class="status-float ${p.status}">${statusLabel[p.status]}</span></div><div class="property-body"><h3>${esc(p.title)}</h3><p class="location">${esc(p.neighborhood)} · ${money(p.price)}</p><small class="photo-count">${photoCount(p)} ${photoCount(p)===1?'foto':'fotos'}</small><button class="btn btn-light full" onclick="ownerForm(${p.id})">Editar anúncio</button></div></article>`).join('');$("#site").innerHTML=appShell('Anunciante',`<div class="account-head"><div><div class="eyebrow">PORTAL DO ANUNCIANTE</div><h1>Meus imóveis.</h1><p>Uma área exclusiva para cadastrar, editar e acompanhar apenas os seus anúncios.</p></div><button class="btn btn-gold" onclick="ownerForm()">＋ Novo anúncio</button></div><div class="metric-row three"><div><b>${ps.length}</b><span>Total</span></div><div><b>${ps.filter(p=>p.status==='published').length}</b><span>Publicados</span></div><div><b>${ps.filter(p=>p.status==='pending').length}</b><span>Em análise</span></div></div><div class="property-grid">${cards||empty('Você ainda não tem imóveis','Crie seu primeiro anúncio e envie as fotos do imóvel.')}</div>`)}
async function ownerForm(id){let p=null;if(id)p=await api('/api/properties/'+id);const imgs=p?.images||[];openModal(`<button class="close" onclick="closeModal()" aria-label="Fechar">×</button><div class="eyebrow">${p?'EDITAR':'NOVO'} ANÚNCIO</div><h2>${p?'Atualizar imóvel':'Cadastrar imóvel'}</h2><p class="modal-subtitle">Preencha os dados e adicione fotos. ${p?'As alterações do anúncio voltam para análise antes de serem publicadas.':'O anúncio será enviado para análise da equipe.'}</p><form id="ownerPropertyForm" onsubmit="saveOwnerProperty(event,${id||0})"><div class="form-grid"><input id="opTitle" class="wide" placeholder="Título do anúncio" value="${esc(p?.title||'')}" required><select id="opType"><option ${p?.type==='Apartamento'?'selected':''}>Apartamento</option><option ${p?.type==='Casa'?'selected':''}>Casa</option><option ${p?.type==='Comercial'?'selected':''}>Comercial</option><option ${p?.type==='Terreno'?'selected':''}>Terreno</option></select><select id="opPurpose"><option value="venda" ${p?.purpose==='venda'||!p?'selected':''}>Venda</option><option value="aluguel" ${p?.purpose==='aluguel'?'selected':''}>Aluguel</option></select><input id="opPrice" type="number" min="0" step="0.01" placeholder="Preço" value="${p?.price||''}" required><input id="opArea" type="number" min="0" step="0.01" placeholder="Área m²" value="${p?.area||''}"><input id="opCity" placeholder="Cidade" value="${esc(p?.city||'Fortaleza')}" required><input id="opNeighborhood" placeholder="Bairro" value="${esc(p?.neighborhood||'')}" required><input id="opBedrooms" type="number" min="0" placeholder="Quartos" value="${p?.bedrooms||0}"><input id="opSuites" type="number" min="0" placeholder="Suítes" value="${p?.suites||0}"><input id="opBathrooms" type="number" min="0" placeholder="Banheiros" value="${p?.bathrooms||0}"><input id="opParking" type="number" min="0" placeholder="Vagas" value="${p?.parking||0}"><textarea id="opDescription" class="wide" placeholder="Descrição">${esc(p?.description||'')}</textarea><input id="opFeatures" class="wide" placeholder="Piscina, varanda, elevador" value="${esc((p?.features||[]).join(', '))}"></div><section class="owner-photo-upload"><div class="upload-head"><div><div class="eyebrow">FOTOS DO IMÓVEL</div><h3>Mostre o imóvel por inteiro.</h3><p>JPG, PNG ou WEBP · até 20 imagens por envio · 10 MB por imagem.</p></div><label class="upload-button"><input id="opImages" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="previewOwnerImages(event)">＋ Adicionar fotos</label></div><div id="ownerImagePreview" class="image-preview-grid">${imgs.map((im,i)=>`<div class="image-preview"><img src="${esc(im.filename.startsWith('http')?im.filename:'/uploads/'+im.filename)}" alt="Foto ${i+1}" loading="lazy"><span>${i===0?'Capa':''}</span></div>`).join('')}</div><div id="ownerImageHint" class="form-note">${imgs.length?`${imgs.length} foto(s) já cadastrada(s). Novas fotos serão adicionadas ao anúncio.`:'Nenhuma foto adicionada ainda. Recomendamos pelo menos 5 fotos.'}</div></section><p class="form-note">${p?'Ao salvar uma alteração, o anúncio volta para análise antes de ser publicado novamente.':'Ao enviar, a equipe receberá o anúncio para análise.'}</p><button class="btn btn-gold full" id="ownerSaveBtn">${p?'Salvar alterações':'Enviar anúncio para análise'}</button></form>`)}
function previewOwnerImages(e){const files=[...(e.target.files||[])];const wrap=$('#ownerImagePreview');if(!wrap)return;wrap.innerHTML=files.map((f,i)=>{const src=URL.createObjectURL(f);return `<div class="image-preview pending"><img src="${src}" alt="Prévia ${i+1}"><span>${i===0?'Nova capa':'Nova foto'}</span></div>`}).join('');$('#ownerImageHint').textContent=files.length?`${files.length} foto(s) selecionada(s). Elas serão enviadas junto com o anúncio.`:'Nenhuma foto selecionada.'}
async function uploadOwnerImages(id,files){if(!files?.length)return null;const form=new FormData();files.forEach(f=>form.append('images',f));return api('/api/owner/properties/'+id+'/images',{method:'POST',body:form})}
async function saveOwnerProperty(e,id){e.preventDefault();const btn=$('#ownerSaveBtn');const files=[...($('#opImages')?.files||[])];const b={title:$("#opTitle").value,type:$("#opType").value,purpose:$("#opPurpose").value,price:$("#opPrice").value,area:$("#opArea").value,city:$("#opCity").value,neighborhood:$("#opNeighborhood").value,bedrooms:$("#opBedrooms").value,suites:$("#opSuites").value,bathrooms:$("#opBathrooms").value,parking:$("#opParking").value,description:$("#opDescription").value,features:$("#opFeatures").value.split(',').map(x=>x.trim()).filter(Boolean)};try{btn.disabled=true;btn.textContent='Salvando…';const saved=await api(id?'/api/owner/properties/'+id:'/api/owner/properties',{method:id?'PATCH':'POST',body:JSON.stringify(b)});if(files.length)await uploadOwnerImages(saved.property?.id||saved.id||id,files);closeModal();toast(files.length?`Anúncio salvo com ${files.length} foto(s).`:'Anúncio enviado para análise.');ownerDashboard()}catch(err){btn.disabled=false;btn.textContent=id?'Salvar alterações':'Enviar anúncio para análise';toast(err.message,'error')}}
async function adminActivity(){const a=await api('/api/admin/activity');$("#site").innerHTML=appShell('Histórico',`<div class="account-head"><div><div class="eyebrow">AUDITORIA</div><h1>Atividade.</h1></div></div><div class="dash-card">${a.map(x=>`<div class="activity-row"><span class="avatar">${esc((x.user_name||'S')[0])}</span><div><b>${esc(x.user_name||'Sistema')}</b><p>${esc(x.action)} · ${esc(x.entity_type||'')}</p><small>${esc(x.details||'')}</small></div><small>${new Date(x.created_at).toLocaleString('pt-BR')}</small></div>`).join('')||empty('Sem registros','As atividades aparecerão aqui.')}</div>`)}
function profileModal(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">MINHA CONTA</div><h2>${esc(state.user.name)}</h2><p>${esc(state.user.email)}</p><form onsubmit="changePassword(event)"><input id="oldPass" type="password" placeholder="Senha atual" required><input id="newPass" type="password" placeholder="Nova senha" minlength="6" required><button class="btn btn-gold full">Alterar senha</button></form>`)}
async function changePassword(e){e.preventDefault();try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:$("#oldPass").value,newPassword:$("#newPass").value})});toast('Senha alterada com segurança.');closeModal()}catch(err){toast(err.message,'error')}}
async function scheduleVisit(id){if(!state.user){openAuth();return}const date=prompt('Data e horário da visita (ex.: 2026-10-02T15:00)');if(!date)return;try{await api('/api/visits',{method:'POST',body:JSON.stringify({property_id:id,visit_date:date})});toast('Solicitação de visita registrada.')}catch(e){toast(e.message,'error')}}
function forgotPassword(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">RECUPERAÇÃO</div><h2>Redefinir senha.</h2><p>Informe o e-mail da sua conta.</p><form onsubmit="requestReset(event)"><input id="resetEmail" type="email" placeholder="seu@email.com" required><button class="btn btn-gold full">Enviar recuperação</button></form>`)}
async function requestReset(e){e.preventDefault();try{const r=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify({email:$('#resetEmail').value})});if(r.devToken){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">MODO LOCAL</div><h2>Token de recuperação.</h2><p>Em produção esse token será enviado por e-mail. Para desenvolvimento local, use-o agora.</p><input id="devResetToken" value="${esc(r.devToken)}" readonly><form onsubmit="resetWithToken(event)"><input id="devResetPass" type="password" minlength="8" placeholder="Nova senha" required><button class="btn btn-gold full">Redefinir senha</button></form>`)}else{closeModal();toast('Se o e-mail existir, a recuperação foi preparada.')}}catch(err){toast(err.message,'error')}}
async function resetWithToken(e){e.preventDefault();try{await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({token:$('#devResetToken').value,password:$('#devResetPass').value})});closeModal();toast('Senha redefinida.');openAuth()}catch(err){toast(err.message,'error')}}
async function logout(){await api('/api/auth/logout',{method:'POST'});state.user=null;state.favorites.clear();toast('Sessão encerrada.');renderHome()}
init().catch(e=>{$('#site').innerHTML=`<div class="fatal"><h1>Imob Pro</h1><p>${esc(e.message)}</p><button class="btn btn-dark" onclick="location.reload()">Tentar novamente</button></div>`});

async function refreshChatBadge(){if(!state.user)return;try{const r=await api('/api/messages/unread');const b=document.getElementById('sideChatBadge');if(b){b.hidden=r.count<1;b.textContent=r.count>9?'9+':r.count}}catch{}}


async function openCompare(){if(!state.compare.size){toast('Adicione pelo menos dois imóveis para comparar.','error');return}const ids=[...state.compare];const props=[];for(const id of ids){try{props.push(await api('/api/properties/'+id))}catch{}}const rows=[['Preço',p=>money(p.price)],['Tipo',p=>p.type],['Área',p=>(p.area||0)+' m²'],['Quartos',p=>p.bedrooms||0],['Suítes',p=>p.suites||0],['Banheiros',p=>p.bathrooms||0],['Vagas',p=>p.parking||0],['Condomínio',p=>money(p.condo||0)],['IPTU',p=>money(p.iptu||0)]];openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">COMPARAÇÃO</div><h2>Compare seus imóveis.</h2><div class="compare-table"><div class="compare-row compare-head"><span></span>${props.map(p=>`<strong>${esc(p.title)}</strong>`).join('')}</div>${rows.map(([label,fn])=>`<div class="compare-row"><span>${label}</span>${props.map(p=>`<b>${esc(fn(p))}</b>`).join('')}</div>`).join('')}</div><div class="modal-actions"><button class="btn btn-light" onclick="closeModal()">Fechar</button><button class="btn btn-gold" onclick="closeModal();openProperty(${props[0]?.id||0})">Abrir imóvel</button></div>`)}
function privacyCenter(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">PRIVACIDADE</div><h2>Controle dos seus dados.</h2><p class="modal-subtitle">Você pode solicitar acesso, correção, portabilidade, informações ou exclusão, conforme aplicável.</p><div class="privacy-actions"><button class="btn btn-light full" onclick="privacyRequest('access')">Solicitar acesso</button><button class="btn btn-light full" onclick="privacyRequest('correction')">Solicitar correção</button><button class="btn btn-light full" onclick="privacyRequest('portability')">Solicitar portabilidade</button><button class="btn btn-light full" onclick="privacyRequest('deletion')">Solicitar exclusão</button></div>`)}
async function privacyRequest(type){try{await api('/api/me/privacy-requests',{method:'POST',body:JSON.stringify({type})});closeModal();toast('Solicitação registrada. A equipe poderá entrar em contato para concluir o atendimento.')}catch(e){toast(e.message,'error')}}
function searchSmart(){const q=String($('#smartSearch')?.value||'').trim();if(!q){searchPage(null,'');return}const params=new URLSearchParams({q});api('/api/properties?'+params).then(ps=>{state.properties=ps;$('#site').innerHTML=shell(`<main class="search-page"><div class="container"><div class="page-top"><div><div class="eyebrow">BUSCA INTELIGENTE</div><h1>Resultados para “${esc(q)}”.</h1><p>${ps.length} imóvel(is) encontrado(s)</p></div></div><div class="results-layout"><aside class="map-placeholder map-rich"><div class="map-grid"></div><div class="map-copy"><span>EXPLORAÇÃO</span><strong>Resultados no mapa</strong><p>A pesquisa combina texto com os dados cadastrados nos anúncios.</p></div></aside><section><div class="property-grid">${ps.map(propertyCard).join('')||empty('Nenhum imóvel encontrado','Tente outra descrição ou use os filtros avançados.')}</div></section></div></div></main>`)}).catch(e=>toast(e.message,'error'))}
function accountPrivacy(){if(!state.user){openAuth('login');return}privacyCenter()}

async function adminAutomations(){const rs=await api('/api/admin/automations');$('#site').innerHTML=appShell('Automações',`<div class="account-head"><div><div class="eyebrow">OPERAÇÃO</div><h1>Automações.</h1><p>Regras simples para reduzir tarefas repetitivas da equipe.</p></div><button class="btn btn-gold" onclick="automationForm()">＋ Nova regra</button></div><div class="admin-list">${rs.map(r=>`<div class="admin-property-row"><div class="avatar large">⚙</div><div class="grow"><b>${esc(r.name)}</b><p>${esc(r.trigger_key)} → ${esc(r.action_key)}</p></div><button class="mini-btn" onclick="toggleAutomation(${r.id},${r.enabled?0:1})">${r.enabled?'Ativa':'Pausada'}</button></div>`).join('')||empty('Nenhuma automação','Crie uma regra para automatizar um fluxo simples.')}</div>`)}
function automationForm(){openModal(`<button class="close" onclick="closeModal()">×</button><div class="eyebrow">AUTOMAÇÃO</div><h2>Nova regra.</h2><form onsubmit="saveAutomation(event)"><input id="arName" placeholder="Ex.: Novo lead → criar tarefa" required><select id="arTrigger"><option value="lead.created">Novo lead</option><option value="visit.created">Nova visita</option><option value="property.published">Imóvel publicado</option></select><select id="arAction"><option value="task.create">Criar tarefa</option><option value="notification.send">Enviar notificação</option></select><button class="btn btn-gold full">Criar regra</button></form>`)}
async function saveAutomation(e){e.preventDefault();try{await api('/api/admin/automations',{method:'POST',body:JSON.stringify({name:$('#arName').value,trigger_key:$('#arTrigger').value,action_key:$('#arAction').value})});closeModal();toast('Automação criada.');adminAutomations()}catch(e){toast(e.message,'error')}}
async function toggleAutomation(id,enabled){try{await api('/api/admin/automations/'+id,{method:'PATCH',body:JSON.stringify({enabled})});adminAutomations()}catch(e){toast(e.message,'error')}}
async function adminPrivacyRequests(){const rs=await api('/api/admin/privacy-requests');$('#site').innerHTML=appShell('Privacidade',`<div class="account-head"><div><div class="eyebrow">LGPD</div><h1>Solicitações de privacidade.</h1><p>Pedidos de acesso, correção, portabilidade e exclusão registrados pelos titulares.</p></div></div><div class="admin-list">${rs.map(r=>`<div class="admin-property-row"><div class="avatar large">◇</div><div class="grow"><b>${esc(r.user_name)} · ${esc(r.type)}</b><p>${esc(r.email)} · ${new Date(r.created_at).toLocaleString('pt-BR')}</p><small>${esc(r.details||'Sem detalhes')}</small></div><span class="status ${r.status==='open'?'pending':'published'}">${esc(r.status)}</span></div>`).join('')||empty('Nenhuma solicitação','Os pedidos dos titulares aparecerão aqui.')}</div>`)}
